def verif(s):
    b=(len(s)>0 ) 
    i=-1
    while (b and (i<len(s)-1)):
        i=i+1
        c=s[i]
        b=('A'<=c<='Z') or c==' '
    return b

def nb_mot(s):
    s1='  '
    while(s.find(s1)!=-1):
        x=s.find(s1)
        s=s[:x]+s[x+1:]
    if s[len(s)-1]==' ':
        s=s[:len(s)-1]
    if s[0]==' ':
        s=s[1:]
    nb=1
    for i in range(0,len(s)):
        if s[i]==' ':
            nb=nb+1
    return nb
